# Re-run region analysis with correct quadrant boundaries
grid = [list(map(int, line.split())) for line in grid_str.strip().split('\n')]

def get_region_analysis(name, grid):
    color_region_sizes = Counter()
    visited = [[False]*21 for _ in range(21)]

    if name == "TL":
        rows, cols = 10, 10
    elif name == "TR":
        rows, cols = 10, 10
    elif name == "BL":
        rows, cols = 10, 10
    elif name == "BR":
        rows, cols = 10, 10

    for r in range(rows):
        for c in range(cols):
            if visited[r][c]:
                continue
            if grid[r][c] not in [0, 5]:
                color = grid[r][c]
                bfs_queue = [(r, c)]
                visited[r][c] = True
                region_size = 0

                while bfs_queue:
                    curr_r, curr_c = bfs_queue.pop()
                    region_size += 1

                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc]:
                            if grid[nr][nc] == color:
                                visited[nr][nc] = True
                                bfs_queue.append((nr, nc))

                if region_size >= 2:
                    color_region_sizes[color] = max(color_region_sizes.get(color, 0), region_size)

    return color_region_sizes

